from typing import List

def is_valid(paren_string):
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack and stack[-1] == '(':
                stack.pop()
            else:
                return False
    return not stack

def separate_paren_groups(paren_string: str) -> List[str]:
    def dfs(index, result, current_string):
        if index == len(paren_string):
            result.append(current_string)
            return

        if paren_string[index] == '(':
            dfs(index + 1, result, current_string + '(')
        elif paren_string[index] == ')':
            if is_valid(paren_string[index+1:]):
                dfs(index + 1, result, current_string + ')')
                dfs(index + 1 + len(current_string[2:]), result, '')
            else:
                return

    result = []
    dfs(0, result, '')
    grouped_strings = []
    for string in result:
        if string and is_valid(string):
            grouped_strings.append(string)
    return grouped_strings
```

